edits.search:
# Get the search path
if ignore_files:
    ignore_file_paths = ConfigLoader.find_ignore_config_files(
        path=path, working_path=working_path
    )

edits.replace:
# Get the search path
if ignore_files:
    ignore_file_paths = ConfigLoader.find_ignore_config_files(
        path=path, working_path=working_path
    )
    # Also check the current working directory for ignore files
    # if it's different from the working_path.
    cwd = os.getcwd()
    if cwd != working_path:
        ignore_file_paths = ignore_file_paths.union(
            ConfigLoader.find_ignore_config_files(
                path=path, working_path=cwd
            )
        )
